theorem card_mul_card_perp {n : ℕ}
    (H : Submodule (ZMod 2) (BooleanSpace n)) :
    Fintype.card H * Fintype.card (perp H) = 2 ^ n

@[simp]
theorem finset_inv_eq_self {n : ℕ}
    (A : Finset (Multiplicative (BooleanSpace n))) : A⁻¹ = A

@[simp]
theorem multiplicative_inv_eq_self {n : ℕ}
    (x : Multiplicative (BooleanSpace n)) : x⁻¹ = x

theorem perp_eq_orthogonal {n : ℕ}
    (H : Submodule (ZMod 2) (BooleanSpace n)) :
    perp H = (dotBilin n).orthogonal H

theorem badPairCount_comm {n : ℕ}
    (A B : Finset (BooleanSpace n)) :
    badPairCount A B = badPairCount B A

theorem card_lowBiasSet_lower {n : ℕ}
    (A B : Finset (BooleanSpace n)) {q : ℝ}
    (hq : 0 < q) (hA : A.Nonempty)
    (hbad :
      (badPairCount A B : ℝ) ≤ q ^ 2 * A.card * B.card) :
    (1 - q) * B.card ≤ (lowBiasSet A B q).card

theorem card_symmDiff_le_of_common_subset {α : Type*}
    [DecidableEq α] {X S T : Finset α}
    (hXS : X ⊆ S) (hXT : X ⊆ T) :
    (S ∆ T).card ≤ (S \ X).card + (T \ X).card

theorem card_symmDiff_le_sdiff_add_sdiff {α : Type*}
    [DecidableEq α] (S T : Finset α) :
    (S ∆ T).card ≤ (S \ T).card + (T \ S).card

theorem highBiasSet_card_bound {n : ℕ}
    (A : Finset (BooleanSpace n)) {q : ℝ}
    (hq0 : 0 ≤ q) (hq4 : 4 * q ≤ 1) :
    ((highBiasSet A q).card : ℝ) *
        (((1 - 4 * q) * A.card) ^ 2) ≤
      Fintype.card (BooleanSpace n) * A.card

theorem lowBiasSet_add_self_subset_highBiasSet {n : ℕ}
    (A B : Finset (BooleanSpace n)) {q : ℝ} :
    lowBiasSet A B q + lowBiasSet A B q ⊆ highBiasSet A q

theorem lowBiasSet_subset_right {n : ℕ}
    (A B : Finset (BooleanSpace n)) (q : ℝ) :
    lowBiasSet A B q ⊆ B

theorem lowBiasSet_sum_card_bound {n : ℕ}
    (A B : Finset (BooleanSpace n)) {q : ℝ}
    (hq0 : 0 ≤ q) (hq4 : 4 * q ≤ 1) :
    (((lowBiasSet A B q + lowBiasSet A B q).card : ℝ) *
        (((1 - 4 * q) * A.card) ^ 2)) ≤
      (Fintype.card (BooleanSpace n) : ℝ) * (A.card : ℝ)

@[simp]
theorem mem_submodulePoints {n : ℕ}
    {L : Submodule (ZMod 2) (BooleanSpace n)}
    {x : BooleanSpace n} :
    x ∈ submodulePoints L ↔ x ∈ L

theorem submodulePoints_perp_card_mul {n : ℕ}
    (L : Submodule (ZMod 2) (BooleanSpace n)) :
    (submodulePoints L).card * (submodulePoints (perp L)).card = 2 ^ n

theorem zero_mem_lowBiasSet {n : ℕ}
    (A B : Finset (BooleanSpace n)) {q : ℝ}
    (hzero : 0 ∈ B) (hq : 0 ≤ q) :
    0 ∈ lowBiasSet A B q

theorem mismatchEntries_card_le_residual {n : ℕ}
    (S T : Finset (BooleanSpace n)) (v : S → ℝ) :
    ((mismatchEntries S T v).card : ℝ) ≤ rankOneResidual S T v

theorem zero_mem_translateFinset {n : ℕ}
    {S : Finset (BooleanSpace n)} {a : BooleanSpace n}
    (ha : a ∈ S) :
    0 ∈ translateFinset S a

theorem robust_inverse_uncertainty_phase_from_implementation
    {n : ℕ} {ε δ q : ℝ}
    {S T : Finset (Cube n)} {f : Cube n → ℂ}
    (h : NearExtremizer ε δ q S T f) :
    ∃ (H : Submodule (ZMod 2) (Cube n)) (a b : Cube n) (c : ℂ),
      HiddenCosetApproximation q S T f H a b c

theorem robust_inverse_uncertainty_phase {n : ℕ} {ε δ q : ℝ}
    {S T : Finset (Cube n)} {f : Cube n → ℂ}
    (h : NearExtremizer ε δ q S T f) :
    ∃ (H : Submodule (ZMod 2) (Cube n)) (a b : Cube n) (c : ℂ),
